export function longestIncreasingPathInAMatrix(matrix            )         {
if(!matrix.length||!matrix[0].length)return 0;const h=matrix.length,w=matrix[0].length,memo=Array.from({length:h},()=>Array(w).fill(0));function visit(r       ,c       )       {if(memo[r][c])return memo[r][c];let best=1;for(const [dr,dc]of [[1,0],[-1,0],[0,1],[0,-1]]){const nr=r+dr,nc=c+dc;if(nr>=0&&nr<h&&nc>=0&&nc<w&&matrix[nr][nc]>matrix[r][c])best=Math.max(best,1+visit(nr,nc));}return memo[r][c]=best;}let result=0;for(let r=0;r<h;r++)for(let c=0;c<w;c++)result=Math.max(result,visit(r,c));return result;
}

